const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let filter='All', opener;
const art={learners:'<div class="mini-people"><span>◎</span><span>✳</span><span>≋</span></div>',values:'<div class="mini-quote">Empathy.<br>Integrity.<br>Purpose.</div>',smart:'<div class="mini-blocks"><span>S</span><span>M</span><span>A</span><span>R</span><span>T</span></div>',arrays:'<div class="mini-blocks"><span>book<small>[0]</small></span><span>pen<small>[1]</small></span><span>lamp<small>[2]</small></span></div>',sequence:'<div class="mini-flow"><span>Discover</span>→<span>Practice</span>→<span>Apply</span></div>',space:'<div class="mini-floor">'+Array(12).fill('<i></i>').join('')+'</div>',management:'<div class="mini-time">60:00<small>A CLASS WITH PURPOSE</small></div>',assessment:'<div class="mini-quote">Feedback.<br>Revision.<br>Growth. ↗</div>',homework:'<div class="mini-quote">Less homework.<br><em>Better</em> homework.</div>',fundamentals:'<div class="mini-flow"><span>Input</span>→<span>Process</span>→<span>Output</span></div>',reflection:'<div class="mini-quote">From<br>&lt;code /&gt;<br>to connection.</div>',material:'<div class="mini-blocks"><span>[0]<small>EXPLORE</small></span><span>[1]<small>PRACTICE</small></span><span>[2]<small>REFLECT</small></span></div>',critique:'<div class="mini-flow"><span>Alignment</span><span>Access</span><span>Creativity</span></div>',strategy:'<div class="mini-quote">The right strategy.<br>For this learner.</div>'};
function render(){const q=$('#search').value.toLowerCase().trim();const list=activities.filter(a=>(filter==='All'||a.category===filter)&&[a.title,a.summary,a.category,a.draft?'reconstructed draft':'original'].join(' ').toLowerCase().includes(q));$('#grid').innerHTML=list.map(a=>`<article class="activity-card"><div class="card-art" aria-hidden="true">${art[a.visual]}</div><div class="card-content"><p class="eyebrow">${a.category.toUpperCase()} <span class="${a.draft?'draft-label':''}">/ ${a.draft?'RECONSTRUCTED DRAFT':'ORIGINAL ACTIVITY'}</span></p><h3>${a.title}</h3><p>${a.summary}</p><button class="text-link" data-open="${a.id}" aria-label="Explore ${escapeHTML(a.title)}">Explore activity <span aria-hidden="true">↗</span></button></div></article>`).join('');$('#count').textContent=`${list.length} of ${activities.length} activities`;$('#empty').hidden=!!list.length;}
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render()}));$('#search').addEventListener('input',render);$('#reset').onclick=()=>{$('#search').value='';$('[data-filter="All"]').click()};
const routine=[['0–5','Entry task','Predict the output of a few lines of code while attendance is taken.'],['5–10','Review & objective','Recall the last lesson, state today’s target, and share success criteria.'],['10–25','Mini-lesson','Live coding with a check for understanding every five minutes.'],['25–50','Practice','Tiered core, extended, and challenge tasks, with teacher check-ins and help cards.'],['50–57','Closure','An exit ticket captures one thing learned and one question remaining.'],['57–60','Reset','Log out, tidy the workspace, and dismiss by row.']];
function showActivity(id){const a=activities.find(x=>x.id===id);if(!a)return;opener=document.activeElement;const href='assets/'+encodeURIComponent(a.file);let extra='';if(a.id==='management')extra='<div class="timeline" role="group" aria-label="Explore class routine">'+routine.map((r,i)=>`<button data-minute="${i}" aria-pressed="${i===0}">${r[0]} min</button>`).join('')+'</div><div class="timeline-detail" aria-live="polite" id="routine"></div>';if(a.id==='sequence'||a.id==='fundamentals')extra='<div class="journey-steps">'+(a.id==='sequence'?['Foundations','Sequencing','Guided critique','Complex analysis','Revise & defend']:['Familiar uses','Components','Hardware & software','File skills','Apply & explain']).map((s,i)=>`<div><b>0${i+1}</b>${s}</div>`).join('')+'</div>';if(a.id==='space')extra='<img class="artifact-image" src="assets/classroom-layout.png" alt="Original classroom floor plan with round tables on the left, desk clusters on the right, and circulation routes between them">';
$('#detail-body').innerHTML=`<p class="eyebrow ${a.draft?'draft-label':''}">${a.category.toUpperCase()} / ${a.draft?'RECONSTRUCTED DRAFT':'ORIGINAL ACTIVITY'}</p><h2 id="detail-title">${a.title}</h2><p class="detail-lead">${a.summary}</p>${a.draft?'<div class="source-note">Recreated from the supplied instructions. This is a new draft for review, not a recovered original submission.</div>':''}<div class="detail-actions">${a.prototypeUrl?`<a class="button" href="${escapeHTML(a.prototypeUrl)}" target="_blank" rel="noopener noreferrer">Open original Figma prototype ↗</a>`:''}<a class="button" href="${href}" target="_blank" rel="noopener">${a.draft?'View source instructions':'Open original artifact'} ↗</a><button class="button" id="download">Download ${a.draft?'draft':'showcase notes'} ↓</button>${['arrays','material'].includes(a.id)?'<button class="button" id="try-lab">Try the interactive lab ↗</button>':''}</div>${extra}<div class="detail-sections">${a.sections.map(s=>`<section><h3>${s.title}</h3><p>${s.body}</p></section>`).join('')}</div>${a.note?`<div class="source-note">${a.note}</div>`:''}${a.id==='learners'?`<details><summary>View the original comparison board</summary><a href="${href}" target="_blank" rel="noopener"><img loading="lazy" class="artifact-image" src="${href}" alt="Original learning styles comparison for Nico, Joshua, and Ethan. Open for full resolution."></a></details>`:''}`;
$('#download').onclick=()=>{const text=`# ${a.title}\n\n${a.draft?'Reconstructed draft — review before submission.':'Showcase summary of the supplied original activity.'}\nSource: ${a.file}\n${a.prototypeUrl?`Original Figma prototype: ${a.prototypeUrl}\n`:''}\n`+a.sections.map(s=>`## ${s.title}\n\n${s.body}`).join('\n\n')+'\n\n'+a.note;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=a.id+(a.draft?'-draft':'-notes')+'.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
if($('#try-lab'))$('#try-lab').onclick=()=>{$('#detail').close();$('#lab').scrollIntoView();$('#explore').focus({preventScroll:true})};if(a.id==='management'){const pick=i=>{$('#routine').innerHTML=`<strong>${routine[i][0]} minutes · ${routine[i][1]}</strong><p>${routine[i][2]}</p>`;$$('[data-minute]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.minute)===i)))};$$('[data-minute]').forEach(b=>b.onclick=()=>pick(Number(b.dataset.minute)));pick(0)};$('#detail').showModal();$('#detail').scrollTop=0;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b)showActivity(b.dataset.open)});$('#close').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>opener?.focus({preventScroll:true}));$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
const supplies=['book','pen','lamp','bag','ruler'];let mode='explore',questionIndex=0,score=0,answered=false,firstTry=true;const questions=[2,0,4,1,3];
$('#slots').innerHTML=supplies.map((s,i)=>`<button class="slot" data-index="${i}" aria-pressed="${i===0}">${s}<small>index ${i}</small></button>`).join('');
function selectSlot(i){$$('.slot').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.index)===i)));$('#lab-output').textContent=`supplies[${i}] → '${supplies[i]}'`}
$$('.slot').forEach(b=>b.onclick=()=>selectSlot(Number(b.dataset.index)));selectSlot(0);
function setMode(next){mode=next;$('#explore').setAttribute('aria-pressed',String(mode==='explore'));$('#practice').setAttribute('aria-pressed',String(mode==='practice'));$('#slots').hidden=mode==='practice';$('#lab-output').hidden=mode==='practice';$('#quiz').hidden=mode==='explore';if(mode==='practice'){questionIndex=0;score=0;renderQuestion()}}
function renderQuestion(){answered=false;firstTry=true;$('#next').hidden=true;$('#restart').hidden=true;$('#feedback').textContent='';$('#question').textContent=`Question ${questionIndex+1} / 5 · What does supplies[${questions[questionIndex]}] return?`;$('#answers').innerHTML=supplies.map(s=>`<button>${s}</button>`).join('');$$('#answers button').forEach(b=>b.onclick=()=>{if(answered)return;if(b.textContent===supplies[questions[questionIndex]]){answered=true;if(firstTry)score++;$('#feedback').textContent='Exactly. Index '+questions[questionIndex]+' retrieves '+b.textContent+'.';$('#next').hidden=false;$('#next').textContent=questionIndex===4?'See results →':'Next question →';$$('#answers button').forEach(x=>x.disabled=true)}else{firstTry=false;$('#feedback').textContent='Keep going. Start with book at index 0, then count forward. Try another value.'}})}
$('#next').onclick=()=>{questionIndex++;if(questionIndex<5)renderQuestion();else{$('#question').textContent='Practice complete';$('#answers').replaceChildren();$('#next').hidden=true;$('#feedback').textContent=`${score}/5 correct on the first attempt (${score*20}%). ${score===5?'You met the source’s 90% target.':'Review the numbered slots, then try again. With five questions, reaching 90% requires 5/5.'} Retries help you learn; the score counts first attempts.`;$('#restart').hidden=false}};$('#restart').onclick=()=>setMode('practice');$('#explore').onclick=()=>setMode('explore');$('#practice').onclick=()=>setMode('practice');
function themeLabel(){$('#theme-toggle').setAttribute('aria-label','Switch to '+(document.documentElement.dataset.theme==='dark'?'light':'dark')+' mode')}$('#theme-toggle').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('learning-theme',document.documentElement.dataset.theme)}catch{}themeLabel()};themeLabel();$('.menu-toggle').onclick=()=>{const open=$('.menu-toggle').getAttribute('aria-expanded')!=='true';$('.menu-toggle').setAttribute('aria-expanded',String(open));$('#nav-links').classList.toggle('open',open)};$$('#nav-links a').forEach(a=>a.onclick=()=>{$('#nav-links').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')});window.addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;$('.scroll-progress').style.transform=`scaleX(${max>0?scrollY/max:0})`},{passive:true});render();
